const sharesDepartment = `-- name: SharesDepartment :one
SELECT EXISTS (
    SELECT 1
    FROM organization.department_member dm1
    INNER JOIN organization.department_member dm2
        ON (dm1.organization_id, dm1.department_id) = (dm2.organization_id, dm2.department_id)
    WHERE dm1.organization_id = $1
      AND dm1.employee_id = $2
      AND dm2.employee_id = $3
) AS shares_department
`

type SharesDepartmentParams struct {
	OrganizationID dbuuid.UUID `json:"organization_id"`
	EmployeeID     dbuuid.UUID `json:"employee_id"`
	EmployeeID_2   dbuuid.UUID `json:"employee_id_2"`
}

func (q *Queries) SharesDepartment(ctx context.Context, db DBTX, arg *SharesDepartmentParams) (bool, error) {
	row := db.QueryRow(ctx, sharesDepartment, arg.OrganizationID, arg.EmployeeID, arg.EmployeeID_2)
	var shares_department bool
	err := row.Scan(&shares_department)
	return shares_department, err
}

