const validateEmployeesExist = `-- name: ValidateEmployeesExist :many
SELECT e.id
FROM organization.employee e
WHERE e.organization_id = $1
  AND e.id = ANY($2::uuid[])
`

type ValidateEmployeesExistParams struct {
	OrganizationID dbuuid.UUID   `json:"organization_id"`
	Column2        []dbuuid.UUID `json:"column_2"`
}

// Validates that employee IDs exist in organization.employee table
// Returns only the IDs that actually exist (for filtering invalid IDs)
func (q *Queries) ValidateEmployeesExist(ctx context.Context, db DBTX, arg *ValidateEmployeesExistParams) ([]dbuuid.UUID, error) {
	rows, err := db.Query(ctx, validateEmployeesExist, arg.OrganizationID, arg.Column2)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []dbuuid.UUID
	for rows.Next() {
		var id dbuuid.UUID
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
